mapper.select:
SELECT FROM ultary_tag WHERE is_deleted = 0
AND ( hashtag LIKE CONCAT(#{q}, '%') OR IFNULL(handle, '') LIKE CONCAT(#{q}, '%') OR IFNULL(title, '') LIKE CONCAT('%', #{q}, '%') )
ORDER BY use_count DESC, tag_id DESC LIMIT #{limit}

SELECT COUNT(1)
FROM ultary_tag
WHERE handle = #{handle}
  AND is_deleted = 0

	AND tag_id != #{excludeTagId}

